typedef enum cl_verdict_t {
    CL_VERDICT_NOTHING_FOUND = 0,
    CL_VERDICT_TRUSTED,
    CL_VERDICT_STRONG_INDICATOR,
    CL_VERDICT_POTENTIALLY_UNWANTED,
} cl_verdict_t;

struct cl_scan_options {
    uint32_t general;
    uint32_t parse;
    uint32_t heuristic;
    uint32_t mail;
    uint32_t dev;
};

enum bytecode_security {
    CL_BYTECODE_TRUST_ALL = 0,
    CL_BYTECODE_TRUST_SIGNED,
    CL_BYTECODE_TRUST_NOTHING
};

enum bytecode_mode {
    CL_BYTECODE_MODE_AUTO = 0,
    CL_BYTECODE_MODE_JIT,
    CL_BYTECODE_MODE_INTERPRETER,
    CL_BYTECODE_MODE_TEST,
    CL_BYTECODE_MODE_OFF
};

struct cli_section_hash {
    unsigned char md5[16];
    size_t len;
};

typedef struct cli_stats_sections {
    size_t nsections;
    struct cli_section_hash *sections;
} stats_section_t;

typedef enum scan_callback {
    CL_SCAN_CALLBACK_PRE_HASH,
    CL_SCAN_CALLBACK_PRE_SCAN,
    CL_SCAN_CALLBACK_POST_SCAN,
    CL_SCAN_CALLBACK_ALERT,
    CL_SCAN_CALLBACK_FILE_TYPE
} cl_scan_callback_t;

typedef cl_error_t (*clcb_file_inspection)(
    int fd,
    const char *type,
    const char **ancestors,
    size_t parent_file_size,
    const char *file_name,
    size_t file_size,
    const char *file_buffer,
    uint32_t recursion_level,
    uint32_t layer_attributes,
    void *context);

enum cl_msg {
    CL_MSG_INFO_VERBOSE = 32,
    CL_MSG_WARN         = 64,
    CL_MSG_ERROR        = 128
};

typedef cl_error_t (*clcb_meta)(
    const char *container_type,
    unsigned long fsize_container,
    const char *filename,
    unsigned long fsize_real,
    int is_encrypted,
    unsigned int filepos_container,
    void *context);

typedef void (*clcb_stats_add_sample)(
    const char *virname,
    const unsigned char *md5,
    size_t size,
    stats_section_t *sections,
    void *cbdata);

struct cl_cvd {
    char *time;
    unsigned int version;
    unsigned int sigs;
    unsigned int fl;
    char *md5;
    char *dsig;
    char *builder;
    unsigned int stime;
};

struct cl_stat {
    char *dir;
    STATBUF *stattab;
    char **statdname;
    unsigned int entries;
};

